import uuid
from datetime import datetime

from sqlalchemy import (
    String, Integer, DateTime, Enum,
    ForeignKey, Boolean, UniqueConstraint, func
)
from sqlalchemy.orm import Mapped, mapped_column

from app.db.session import Base


class AttendanceEvent(Base):
    __tablename__ = "attendance_events"

    id: Mapped[int] = mapped_column(
        Integer, primary_key=True
    )

    # Generated by the Edge Agent; makes retries idempotent.
    event_uuid: Mapped[str] = mapped_column(
        String(36),
        unique=True,
        nullable=False,
        default=lambda: str(uuid.uuid4())
    )

    employee_id: Mapped[int] = mapped_column(
        ForeignKey("employees.id"), nullable=False, index=True
    )

    camera_id: Mapped[int] = mapped_column(
        ForeignKey("cameras.id"), nullable=False
    )

    event_type: Mapped[str] = mapped_column(
        Enum("ENTRY", "EXIT", name="attendance_event_type"),
        nullable=False
    )

    # Event time supplied by the trusted Edge Agent.
    occurred_at: Mapped[datetime] = mapped_column(
        DateTime, nullable=False, index=True
    )

    received_at: Mapped[datetime] = mapped_column(
        DateTime, server_default=func.now(), nullable=False
    )

    confidence_score: Mapped[float | None] = mapped_column(
        nullable=True
    )

    is_accepted: Mapped[bool] = mapped_column(
        Boolean, default=True, nullable=False
    )

    rejection_reason: Mapped[str | None] = mapped_column(
        String(255), nullable=True
    )


class AttendanceSession(Base):
    __tablename__ = "attendance_sessions"

    id: Mapped[int] = mapped_column(
        Integer, primary_key=True
    )

    employee_id: Mapped[int] = mapped_column(
        ForeignKey("employees.id"), nullable=False, index=True
    )

    entry_event_id: Mapped[int] = mapped_column(
        ForeignKey("attendance_events.id"),
        nullable=False,
        unique=True
    )

    exit_event_id: Mapped[int | None] = mapped_column(
        ForeignKey("attendance_events.id"),
        nullable=True,
        unique=True
    )

    entry_time: Mapped[datetime] = mapped_column(
        DateTime, nullable=False
    )

    exit_time: Mapped[datetime | None] = mapped_column(
        DateTime, nullable=True
    )

    worked_minutes: Mapped[int | None] = mapped_column(
        Integer, nullable=True
    )


class DailyAttendance(Base):
    __tablename__ = "daily_attendance"

    __table_args__ = (
        UniqueConstraint(
            "employee_id",
            "work_date",
            name="uq_employee_daily_attendance"
        ),
    )

    id: Mapped[int] = mapped_column(
        Integer, primary_key=True
    )

    employee_id: Mapped[int] = mapped_column(
        ForeignKey("employees.id"), nullable=False, index=True
    )

    work_date: Mapped[datetime] = mapped_column(
        DateTime, nullable=False
    )

    worked_minutes: Mapped[int] = mapped_column(
        Integer, default=0, nullable=False
    )

    overtime_minutes: Mapped[int] = mapped_column(
        Integer, default=0, nullable=False
    )

    status: Mapped[str] = mapped_column(
        Enum(
            "PRESENT",
            "HALF_DAY",
            "ABSENT",
            "INCOMPLETE",
            name="daily_attendance_status"
        ),
        default="ABSENT",
        nullable=False
    )

    is_finalized: Mapped[bool] = mapped_column(
        Boolean, default=False, nullable=False
    )